contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount || depositAmount == 0);
        require(collectAmount == depositAmount);

        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cEtherBefore = address(c).balance;

        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint balAfterDeposit = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cEtherAfterDeposit = address(c).balance;

        bool reverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balAfterCollect = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cEtherAfterCollect = address(c).balance;

        assert(!reverted && balAfterDeposit == balBefore + depositAmount && balAfterCollect == balBefore && cEtherAfterDeposit == cEtherBefore + depositAmount && cEtherAfterCollect == cEtherBefore);
    }

    receive() external payable {}
}

